# langs/cow.py
"""COW — язык из «moo»-слов. Разновидность Brainfuck."""

from core.base import Language
from core.translate import TRANSPILERS


COW_TO_BF = {
    "MoO": ">", "MOo": "<", "moO": "+", "mOo": "-",
    "OOO": ".", "Moo": ",", "MOO": "[", "moo": "]",
}
BF_TO_COW = {v: k + " " for k, v in COW_TO_BF.items()}


def _cow_to_bf(src):
    words = []
    i = 0
    while i < len(src):
        w = src[i:i+3]
        if w in COW_TO_BF:
            words.append(COW_TO_BF[w])
            i += 3
        else:
            i += 1
    return "".join(words)


def _cow_to_python(src):
    bf = _cow_to_bf(src)
    lines = ["_tape = [0] * 30000", "_ptr = 0"]
    for c in bf:
        if c == '>':
            lines.append("_ptr = (_ptr + 1) % 30000")
        elif c == '<':
            lines.append("_ptr = (_ptr - 1) % 30000")
        elif c == '+':
            lines.append("_tape[_ptr] = (_tape[_ptr] + 1) & 0xFF")
        elif c == '-':
            lines.append("_tape[_ptr] = (_tape[_ptr] - 1) & 0xFF")
        elif c == '.':
            lines.append("print(chr(_tape[_ptr]), end='')")
    return "\n".join(lines) + "\n"


def _bf_print(text):
    """COW-код, печатающий текст. Перед каждым символом сбрасывает ячейку."""
    parts = []
    for ch in text:
        n = ord(ch) & 0xFF
        parts.append("MOO mOo moo ")   # [-] — обнулить ячейку
        parts.append("moO " * n)        # набрать код символа
        parts.append("OOO ")            # вывести
    return "".join(parts)


